  .nav-links{position:fixed;top:var(--nav-h);left:0;right:0;flex-direction:column;background:rgba(7,5,6,.97);backdrop-filter:blur(16px);padding:16px 4% 30px;border-bottom:1px solid var(--border);gap:0;transform:translateY(-14px);opacity:0;visibility:hidden;transition:.35s}
  .nav-links.open{transform:none;opacity:1;visibility:visible}
  .nav-links a{padding:18px 4px;font-size:.9rem;border-bottom:1px solid rgba(214,173,96,.12)}
  .nav-links a::after{display:none}
  .nav-links .mob-cta{display:block;margin-top:18px}
  .foot{grid-template-columns:1fr 1fr}.foot>div:first-child{grid-column:1/-1}
  .m-artist{grid-template-columns:1fr}.m-artist .ph{aspect-ratio:16/10;min-height:0}
  .scroll-cue{display:none}
}
@media (min-width:861px){.mob-cta{display:none}}
@media (max-width:640px){
