 return '<article class="artist glass rv" style="--d:'+((i%4)*.08)+'s"><div class="ph"><img loading="lazy" src="'+U(a.q,1200,900)+'" alt="'+esc(a.n)+' — '+esc(a.r)+'"></div><div class="artist-body"><span class="role">'+esc(a.r)+'</span><h3>'+esc(a.n)+'</h3><p>'+esc(a.t)+'</p><button class="btn btn-sm" type="button" data-artist="'+i+'" aria-haspopup="dialog">View details</button></div></article>';
