/* image fallback: keep velvet gradient if remote image fails */
$$('img').forEach(function(img){
 function bad(){img.style.opacity='0'}
 img.addEventListener('error',bad);
 if(img.complete&&img.naturalWidth===0&&img.getAttribute('src'))bad();
});

/* ---------- toast ---------- */
function toast(msg){
 var t=document.createElement('div');t.className='toast';t.textContent=msg;$('#toasts').appendChild(t);
 setTimeout(function(){t.classList.add('out');setTimeout(function(){t.remove()},400)},4200);
}

/* ---------- nav ---------- */
var nav=$('#nav'),burger=$('#burger'),links=$('#navLinks');
function onScroll(){nav.classList.toggle('scrolled',window.scrollY>30)}
window.addEventListener('scroll',onScroll,{passive:true});onScroll();
function setMenu(o){links.classList.toggle('open',o);burger.setAttribute('aria-expanded',o)}
burger.addEventListener('click',function(){setMenu(!links.classList.contains('open'))});
$$('a[href^="#"]').forEach(function(a){
 a.addEventListener('click',function(e){
  var id=a.getAttribute('href');setMenu(false);
  var el=id.length>1&&$(id);if(!el)return;
  e.preventDefault();el.scrollIntoView({behavior:'smooth',block:'start'});
  history.replaceState(null,'',id);
 });
});
/* active nav */
var navA=$$('#navLinks a[href^="#"]').filter(function(a){return !a.classList.contains('btn')});
var secs=navA.map(function(a){return $(a.getAttribute('href'))});
function spy(){
 var y=window.scrollY+window.innerHeight*.35,cur=-1;
 secs.forEach(function(s,i){if(s&&s.offsetTop<=y)cur=i});
 var last=document.documentElement.scrollHeight-window.innerHeight-4<=window.scrollY;
 // newsletter/footer follow FAQ; only keep FAQ active while inside it
 var faqS=$('#faq');if(cur===secs.indexOf(faqS)&&y>faqS.offsetTop+faqS.offsetHeight)cur=-1;
 navA.forEach(function(a,i){var on=i===cur;a.classList.toggle('active',on);on?a.setAttribute('aria-current','true'):a.removeAttribute('aria-current')});
}
window.addEventListener('scroll',spy,{passive:true});window.addEventListener('resize',spy);spy();

/* ---------- reveal ---------- */
var rv=$$('.rv');
if('IntersectionObserver' in window){
 var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12,rootMargin:'0px 0px -40px 0px'});
 rv.forEach(function(el){io.observe(el)});
}else rv.forEach(function(el){el.classList.add('in')});

/* ---------- modals ---------- */
var openOv=null,lastFocus=null;
var FOC='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
function openModal(ov){
 lastFocus=document.activeElement;openOv=ov;
 ov.classList.add('open');ov.setAttribute('aria-hidden','false');document.body.classList.add('lock');
 setTimeout(function(){var f=$('.close',ov);f&&f.focus()},50);
}
function closeModal(){
 if(!openOv)return;
 openOv.classList.remove('open');openOv.setAttribute('aria-hidden','true');document.body.classList.remove('lock');
 openOv=null;if(lastFocus&&lastFocus.focus)lastFocus.focus();
}
$$('.overlay').forEach(function(ov){
 ov.addEventListener('mousedown',function(e){if(e.target===ov)closeModal()});
 $$('[data-close]',ov).forEach(function(b){b.addEventListener('click',function(){
   var href=b.getAttribute('href');closeModal();
   if(href&&href.charAt(0)==='#'){var el=$(href);el&&setTimeout(function(){el.scrollIntoView({behavior:'smooth'})},50)}
 })});
});
document.addEventListener('keydown',function(e){
 if(!openOv)return;
 if(e.key==='Escape'){e.preventDefault();closeModal();return}
 if(e.key==='Tab'){
  var f=$$(FOC,openOv).filter(function(x){return x.offsetParent!==null});
  if(!f.length)return;var a=f[0],z=f[f.length-1];
  if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}
  else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}
  else if(!openOv.contains(document.activeElement)){e.preventDefault();a.focus()}
 }
});

