 $('#amName').textContent=a.n;$('#amRole').textContent=a.r;$('#amBio').textContent=a.b;$('#amSession').textContent='Session: '+a.s;
 openModal($('#artistOv'));
});
$('#amImg').addEventListener('error',function(){this.style.opacity='0'});

/* ---------- ticket modal ---------- */
var form=$('#coForm'),done=$('#coDone'),qty=$('#coQty'),tierSel=$('#coTier');
var mailRe=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function setErr(input,errEl,msg){errEl.textContent=msg||'';if(input){msg?input.setAttribute('aria-invalid','true'):input.removeAttribute('aria-invalid')}}
function clampQty(){var n=parseInt(qty.value,10);return isNaN(n)?NaN:n}
function updTotal(){
 var t=tiers[tierSel.value],n=clampQty();
 $('#coTierName').textContent=t.n;
 $('#coTotal').textContent='€'+(isNaN(n)||n<1||n>10?0:t.p*n);
}
function openTicket(key){
 tierSel.value=key;qty.value=1;form.reset&&0;
 ['coName','coEmail'].forEach(function(id){$('#'+id).value=''});$('#coTerms').checked=false;
 [['coName','coNameE'],['coEmail','coEmailE'],['coQty','coQtyE']].forEach(function(p){setErr($('#'+p[0]),$('#'+p[1]),'')});
 setErr(null,$('#coTermsE'),'');
 form.hidden=false;done.hidden=true;updTotal();openModal($('#ticketOv'));
}
$$('[data-tier]').forEach(function(b){b.addEventListener('click',function(){openTicket(b.getAttribute('data-tier'))})});
tierSel.addEventListener('change',updTotal);qty.addEventListener('input',updTotal);
$('#qMinus').addEventListener('click',function(){var n=clampQty()||1;qty.value=Math.max(1,n-1);updTotal()});
$('#qPlus').addEventListener('click',function(){var n=clampQty()||0;qty.value=Math.min(10,n+1);updTotal()});
form.addEventListener('submit',function(e){
 e.preventDefault();
 var name=$('#coName'),mail=$('#coEmail'),terms=$('#coTerms'),ok=true,first=null;
 function bad(el,er,m){setErr(el,er,m);ok=false;if(!first)first=el}
 var nv=name.value.trim();
 nv.length<2?bad(name,$('#coNameE'),'Please enter the attendee name.'):setErr(name,$('#coNameE'),'');
 mailRe.test(mail.value.trim())?setErr(mail,$('#coEmailE'),''):bad(mail,$('#coEmailE'),'Please enter a valid email address.');
 var n=clampQty();
 (isNaN(n)||n<1||n>10||String(n)!==qty.value.trim())?bad(qty,$('#coQtyE'),'Choose between 1 and 10 tickets.'):setErr(qty,$('#coQtyE'),'');
 terms.checked?setErr(null,$('#coTermsE'),''):bad(terms,$('#coTermsE'),'Please accept the terms to continue.');
 if(!ok){first.focus();return}
 var t=tiers[tierSel.value];
 $('#coDoneMsg').textContent=n+' × '+t.n+' reserved for '+nv+' — total €'+(t.p*n)+'. A confirmation would be sent to '+mail.value.trim()+' (demo only).';
 form.hidden=true;done.hidden=false;done.focus();
 toast('Reservation confirmed — see you after dark, '+nv.split(' ')[0]+'.');
});

/* ---------- FAQ ---------- */
$('#faqList').addEventListener('click',function(e){
 var b=e.target.closest('.faq-q');if(!b)return;
 var open=b.getAttribute('aria-expanded')==='true';
 $$('.faq-q').forEach(function(x){x.setAttribute('aria-expanded','false');$('#'+x.getAttribute('aria-controls')).classList.remove('open')});
 if(!open){b.setAttribute('aria-expanded','true');$('#'+b.getAttribute('aria-controls')).classList.add('open')}
});

/* ---------- newsletter ---------- */
var ne=$('#newsEmail');
$('#newsForm').addEventListener('submit',function(e){
 e.preventDefault();var v=ne.value.trim();
 if(!v){setErr(ne,$('#newsErr'),'Please enter your email.');ne.focus();return}
 if(!mailRe.test(v)){setErr(ne,$('#newsErr'),'That email doesn’t look right.');ne.focus();return}
 setErr(ne,$('#newsErr'),'');ne.value='';toast('You’re on the list. Welcome to the night.');
});
ne.addEventListener('input',function(){if(ne.getAttribute('aria-invalid'))setErr(ne,$('#newsErr'),'')});
['coName','coEmail'].forEach(function(id){$('#'+id).addEventListener('input',function(){if(this.getAttribute('aria-invalid'))setErr(this,$('#'+id+'E'),'')})});

/* ---------- calendar (.ics) ---------- */
function saveICS(){
 var stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
 var lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ARTIFACT//Museum Night//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',
  'UID:artifact-museum-night-20261018@artifact.example','DTSTAMP:'+stamp,
  'DTSTART:20261018T190000','DTEND:20261019T020000',
  'SUMMARY:ARTIFACT: Museum Night','LOCATION:The Old Gallery\\, Warsaw',
  'DESCRIPTION:A cinematic after-hours museum event with exhibitions\\, performances\\, talks\\, and guided tours.',
  'END:VEVENT','END:VCALENDAR'];
 var blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});
 var url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='artifact-museum-night.ics';a.style.display='none';
 document.body.appendChild(a);a.click();
 setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},500);
 toast('Calendar file downloaded — open it to add the event.');
}
$$('[data-ics]').forEach(function(b){b.addEventListener('click',saveICS)});
})();
</script>
